syntax:
std::merge(first1, last1, first2, last2, result);
// Parameters:
// - first1, last1: Iterators defining the first sorted range
// - first2, last2: Iterators defining the second sorted range
// - result: Output iterator where the merged range is written
// Implementation notes: The function assumes both ranges are sorted. It uses a stable merge, meaning equal elements retain their original order. Internally, it may use a temporary array for merging if the output overlaps with inputs, affecting memory layout and potentially triggering dynamic memory allocation.

code_example:
#include <iostream>
#include <vector>
#include <algorithm>
#include <iterator>

int main() {
    std::vector<int> coll1 = {1, 2, 3, 4, 5, 6};
    std::vector<int> coll2 = {3, 4, 5, 6, 7, 8};
    std::vector<int> merged(coll1.size() + coll2.size());  // Pre-allocate for efficiency

    std::merge(coll1.begin(), coll1.end(), coll2.begin(), coll2.end(), merged.begin());

    std::cout << "coll1: ";
    for (int elem : coll1) std::cout << elem << " ";
    std::cout << std::endl;

    std::cout << "coll2: ";
    for (int elem : coll2) std::cout << elem << " ";
    std::cout << std::endl;

    std::cout << "merged: ";
    for (int elem : merged) std::cout << elem << " ";
    std::cout << std::endl;

    return 0;
}
